import { parseBoardCode } from './boardCode.ts';
import { generateBoard } from './deck.ts';
import type { Board } from './deck.ts';
import { CLOSED_SELECTION, MISMATCH_MS, SELECTION } from './selection.ts';
import type { Selection } from './selection.ts';

export const MAX_MOVES = 999_999;
export const MAX_ELAPSED_MS = 359_999_999;

export type GameState = Readonly<{
  board: Board;
  matched: readonly number[];
  selection: Selection;
  moves: number;
  elapsedMs: number;
  started: boolean;
}>;

export function createGame(boardCode: string): GameState | null {
  const description = parseBoardCode(boardCode);
  if (description === null) return null;
  return Object.freeze({
    board: generateBoard(description), matched: Object.freeze([]),
    selection: CLOSED_SELECTION, moves: 0, elapsedMs: 0, started: false,
  });
}

export function isWon(state: GameState): boolean {
  return state.matched.length === state.board.deck.length;
}

export function pairCount(state: GameState): number {
  return state.matched.length / 2;
}

export function isRevealed(state: GameState, index: number): boolean {
  if (state.matched.includes(index)) return true;
  switch (state.selection.kind) {
    case SELECTION.closed: return false;
    case SELECTION.one: return state.selection.index === index;
    case SELECTION.mismatch: return state.selection.first === index || state.selection.second === index;
  }
}

export function activateCard(state: GameState, index: number): GameState {
  if (!Number.isSafeInteger(index) || index < 0 || index >= state.board.deck.length
    || state.matched.includes(index) || isWon(state)) return state;
  switch (state.selection.kind) {
    case SELECTION.mismatch: return state;
    case SELECTION.closed:
      return Object.freeze({ ...state, started: true, selection: Object.freeze({ kind: SELECTION.one, index }) });
    case SELECTION.one: {
      const first = state.selection.index;
      if (first === index) return state;
      const moves = Math.min(MAX_MOVES, state.moves + 1);
      if (state.board.deck[first] === state.board.deck[index]) {
        return Object.freeze({ ...state, moves, selection: CLOSED_SELECTION,
          matched: Object.freeze([...state.matched, first, index]) });
      }
      return Object.freeze({ ...state, moves, selection: Object.freeze({
        kind: SELECTION.mismatch, first, second: index, remainingMs: MISMATCH_MS,
      }) });
    }
  }
}

// Fractional active milliseconds are retained; only serialization rounds them down.
export function advanceGame(state: GameState, milliseconds: number): GameState {
  if (!Number.isFinite(milliseconds) || milliseconds <= 0 || !state.started || isWon(state)) return state;
  const elapsedMs = Math.min(MAX_ELAPSED_MS, state.elapsedMs + milliseconds);
  const selection = state.selection;
  switch (selection.kind) {
    case SELECTION.closed:
    case SELECTION.one:
      return elapsedMs === state.elapsedMs ? state : Object.freeze({ ...state, elapsedMs });
    case SELECTION.mismatch:
      return Object.freeze({ ...state, elapsedMs, selection: milliseconds >= selection.remainingMs
        ? CLOSED_SELECTION
        : Object.freeze({ ...selection, remainingMs: selection.remainingMs - milliseconds }) });
  }
}

export function formatTime(elapsedMs: number): string {
  const seconds = Math.floor(elapsedMs / 1000);
  return `${Math.floor(seconds / 60)}:${String(seconds % 60).padStart(2, '0')}`;
}
import type { BoardCode } from './boardCode.ts';
import { boundedRandom } from './random.ts';

export type Board = BoardCode & Readonly<{ deck: readonly number[] }>;

export function generateBoard(description: BoardCode): Board {
  const deck = Array.from({ length: description.size ** 2 }, (_, index) => Math.floor(index / 2));
  let state = description.seed;
  for (let index = deck.length - 1; index > 0; index -= 1) {
    const draw = boundedRandom(state, index + 1);
    state = draw.state;
    const first = deck[index];
    const second = deck[draw.value];
    if (first === undefined || second === undefined) throw new Error('Invalid shuffle position.');
    deck[index] = second;
    deck[draw.value] = first;
  }
  return Object.freeze({ ...description, deck: Object.freeze(deck) });
}
import { SELECTION } from './selection.ts';
import { decodeSelection } from './snapshotSelection.ts';
import { createGame, isWon, MAX_ELAPSED_MS, MAX_MOVES, pairCount } from './state.ts';
import type { GameState } from './state.ts';
import { hasExactKeys, isInteger, isRecord, parseLimitedJson } from './validation.ts';

export const SNAPSHOT_VERSION = 1;
export const SNAPSHOT_MAX_BYTES = 65_536;
const SNAPSHOT_KEYS = ['version', 'boardCode', 'matched', 'selection', 'moves', 'elapsedMs', 'started'];

export function encodeSnapshot(state: GameState): string {
  const selection = state.selection.kind === SELECTION.mismatch
    ? { ...state.selection, remainingMs: Math.max(1, Math.floor(state.selection.remainingMs)) }
    : state.selection;
  return JSON.stringify({ version: SNAPSHOT_VERSION, boardCode: state.board.code,
    matched: state.matched, selection, moves: state.moves,
    elapsedMs: Math.floor(state.elapsedMs), started: state.started }, null, 2);
}

function decodeMatched(value: unknown, game: GameState): readonly number[] | null {
  if (!Array.isArray(value)) return null;
  const positions: number[] = [];
  for (const position of value) {
    if (!isInteger(position, game.board.deck.length - 1) || positions.includes(position)) return null;
    positions.push(position);
  }
  const counts = new Map<number, number>();
  for (const position of positions) {
    const face = game.board.deck[position];
    if (face === undefined) return null;
    counts.set(face, (counts.get(face) ?? 0) + 1);
  }
  return [...counts.values()].every((count) => count === 2) ? Object.freeze(positions) : null;
}

export function decodeSnapshot(text: string): GameState | null {
  const value = parseLimitedJson(text, SNAPSHOT_MAX_BYTES);
  if (!isRecord(value) || !hasExactKeys(value, SNAPSHOT_KEYS) || value.version !== SNAPSHOT_VERSION
    || typeof value.boardCode !== 'string' || typeof value.started !== 'boolean'
    || !isInteger(value.moves, MAX_MOVES) || !isInteger(value.elapsedMs, MAX_ELAPSED_MS)) return null;
  const game = createGame(value.boardCode);
  if (game === null) return null;
  const matched = decodeMatched(value.matched, game);
  if (matched === null) return null;
  const selection = decodeSelection(value.selection, game, matched);
  if (selection === null) return null;
  const restored = Object.freeze({ ...game, matched, selection, moves: value.moves,
    elapsedMs: value.elapsedMs, started: value.started });
  const minimumMoves = pairCount(restored) + (selection.kind === SELECTION.mismatch ? 1 : 0);
  if (restored.moves < minimumMoves || (isWon(restored) && selection.kind !== SELECTION.closed)) return null;
  if (!restored.started && (restored.moves !== 0 || restored.elapsedMs !== 0
    || matched.length !== 0 || selection.kind !== SELECTION.closed)) return null;
  if (restored.started && restored.moves === 0 && selection.kind !== SELECTION.one) return null;
  return restored;
}
import { activateCard, advanceGame, createGame } from './state.ts';
import type { GameState } from './state.ts';
import { hasExactKeys, isInteger, isRecord, parseLimitedJson } from './validation.ts';

export const REPLAY_VERSION = 1;
export const REPLAY_MAX_BYTES = 1_048_576;
export const REPLAY_MAX_ACTIONS = 10_000;
type ReplayAction = Readonly<{ atMs: number; index: number }>;

function decodeActions(value: unknown, cardCount: number, endMs: number): readonly ReplayAction[] | null {
  if (!Array.isArray(value) || value.length > REPLAY_MAX_ACTIONS) return null;
  const actions: ReplayAction[] = [];
  let previousMs = 0;
  for (const action of value) {
    if (!isRecord(action) || !hasExactKeys(action, ['atMs', 'index'])
      || !isInteger(action.atMs) || !isInteger(action.index, cardCount - 1)
      || action.atMs < previousMs || action.atMs > endMs) return null;
    actions.push({ atMs: action.atMs, index: action.index });
    previousMs = action.atMs;
  }
  return actions;
}

export function replayGame(text: string): GameState | null {
  const value = parseLimitedJson(text, REPLAY_MAX_BYTES);
  if (!isRecord(value) || !hasExactKeys(value, ['version', 'boardCode', 'actions', 'endMs'])
    || value.version !== REPLAY_VERSION || typeof value.boardCode !== 'string' || !isInteger(value.endMs)) return null;
  let state = createGame(value.boardCode);
  if (state === null) return null;
  const actions = decodeActions(value.actions, state.board.deck.length, value.endMs);
  if (actions === null) return null;
  let atMs = 0;
  for (const action of actions) {
    state = activateCard(advanceGame(state, action.atMs - atMs), action.index);
    atMs = action.atMs;
  }
  return advanceGame(state, value.endMs - atMs);
}

export const GRID_SIZES = [4, 6, 8, 10, 12, 14, 16] as const;
export type GridSize = (typeof GRID_SIZES)[number];
export const MAX_SEED = 2_147_483_646;

export type BoardCode = Readonly<{ code: string; size: GridSize; seed: number }>;

export function isGridSize(value: unknown): value is GridSize {
  return GRID_SIZES.some((size) => size === value);
}

export function parseBoardCode(code: string): BoardCode | null {
  const match = /^np1-(4|6|8|10|12|14|16)-([1-9][0-9]*)$/.exec(code);
  if (match === null || match[0] !== code) return null;
  const size = Number(match[1]);
  const seed = Number(match[2]);
  if (!isGridSize(size) || !Number.isSafeInteger(seed) || seed > MAX_SEED) return null;
  return Object.freeze({ code, size, seed });
}
const MODULUS = 2_147_483_647;
const RANDOM_VALUES = MODULUS - 1;

export function nextRandomState(state: number): number {
  // The largest product is below 2^53, so integer multiplication is exact.
  return (state * 16_807) % MODULUS;
}

export function boundedRandom(state: number, bound: number): Readonly<{ state: number; value: number }> {
  const limit = Math.floor(RANDOM_VALUES / bound) * bound;
  let next = state;
  do {
    next = nextRandomState(next);
  } while (next - 1 >= limit);
  return { state: next, value: (next - 1) % bound };
}
export const SELECTION = { closed: 'closed', one: 'one', mismatch: 'mismatch' } as const;
export const MISMATCH_MS = 800;

export type Selection =
  | Readonly<{ kind: typeof SELECTION.closed }>
  | Readonly<{ kind: typeof SELECTION.one; index: number }>
  | Readonly<{ kind: typeof SELECTION.mismatch; first: number; second: number; remainingMs: number }>;

export const CLOSED_SELECTION: Selection = Object.freeze({ kind: SELECTION.closed });
export function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

export function hasExactKeys(value: Record<string, unknown>, keys: readonly string[]): boolean {
  return Object.keys(value).length === keys.length && keys.every((key) => Object.hasOwn(value, key));
}

export function isInteger(value: unknown, maximum = Number.MAX_SAFE_INTEGER): value is number {
  return typeof value === 'number' && Number.isSafeInteger(value) && value >= 0 && value <= maximum;
}

export function parseLimitedJson(text: string, maximumBytes: number): unknown {
  if (new TextEncoder().encode(text).length > maximumBytes) return null;
  try {
    const value: unknown = JSON.parse(text);
    return value;
  } catch {
    return null;
  }
}
import { CLOSED_SELECTION, MISMATCH_MS, SELECTION } from './selection.ts';
import type { Selection } from './selection.ts';
import type { GameState } from './state.ts';
import { hasExactKeys, isInteger, isRecord } from './validation.ts';

export function decodeSelection(value: unknown, game: GameState, matched: readonly number[]): Selection | null {
  if (!isRecord(value)) return null;
  const available = (index: unknown): index is number =>
    isInteger(index, game.board.deck.length - 1) && !matched.includes(index);
  switch (value.kind) {
    case SELECTION.closed:
      return hasExactKeys(value, ['kind']) ? CLOSED_SELECTION : null;
    case SELECTION.one:
      return hasExactKeys(value, ['kind', 'index']) && available(value.index)
        ? Object.freeze({ kind: SELECTION.one, index: value.index }) : null;
    case SELECTION.mismatch:
      if (!hasExactKeys(value, ['kind', 'first', 'second', 'remainingMs'])
        || !available(value.first) || !available(value.second) || value.first === value.second
        || game.board.deck[value.first] === game.board.deck[value.second]
        || !isInteger(value.remainingMs, MISMATCH_MS) || value.remainingMs < 1) return null;
      return Object.freeze({ kind: SELECTION.mismatch, first: value.first,
        second: value.second, remainingMs: value.remainingMs });
    default: return null;
  }
}

import { describe, expect, it } from 'vitest';
import { GRID_SIZES } from './boardCode.ts';
import { activateCard, advanceGame, createGame, formatTime, isRevealed, isWon,
  MAX_ELAPSED_MS, MAX_MOVES, pairCount } from './state.ts';

function initial(code = 'np1-4-1') {
  const state = createGame(code);
  if (state === null) throw new Error('Invalid test board.');
  return state;
}

describe('game transitions', () => {
  it('ignores invalid positions and the clock before the first reveal', () => {
    const state = initial();
    expect(advanceGame(state, 1000)).toBe(state);
    for (const index of [-1, 16, 0.5, NaN, Infinity]) expect(activateCard(state, index)).toBe(state);
    expect(createGame('bad')).toBeNull();
  });

  it('starts on a valid reveal, ignores its repeat, then matches immediately', () => {
    const hidden = initial();
    const one = activateCard(hidden, 0);
    expect(one.started).toBe(true);
    expect(one.moves).toBe(0);
    expect(isRevealed(one, 0)).toBe(true);
    expect(isRevealed(one, 11)).toBe(false);
    expect(activateCard(one, 0)).toBe(one);
    const matched = activateCard(advanceGame(one, 1250), 11);
    expect(matched.moves).toBe(1);
    expect(pairCount(matched)).toBe(1);
    expect(matched.selection).toEqual({ kind: 'closed' });
    expect(matched.elapsedMs).toBe(1250);
    expect(activateCard(matched, 0)).toBe(matched);
    expect(hidden.matched).toEqual([]);
    expect(hidden.selection).toEqual({ kind: 'closed' });
    expect(matched.board).toBe(hidden.board);
  });

  it('blocks activation during a miss and closes both at exactly 800 active ms', () => {
    const missed = activateCard(activateCard(initial(), 0), 1);
    expect(missed.moves).toBe(1);
    expect(activateCard(missed, 2)).toBe(missed);
    const waiting = advanceGame(missed, 799);
    expect(waiting.selection).toEqual({ kind: 'mismatch', first: 0, second: 1, remainingMs: 1 });
    expect(isRevealed(waiting, 0)).toBe(true);
    expect(isRevealed(waiting, 1)).toBe(true);
    expect(advanceGame(waiting, 1).selection).toEqual({ kind: 'closed' });
    expect(missed.selection.kind).toBe('mismatch');
  });

  it('retains fractional time and still closes misses at the elapsed cap', () => {
    const missed = activateCard(activateCard(initial(), 0), 1);
    const fractional = advanceGame(advanceGame(missed, 0.25), 0.5);
    expect(fractional.elapsedMs).toBe(0.75);
    expect(fractional.selection).toEqual({ kind: 'mismatch', first: 0, second: 1, remainingMs: 799.25 });
    const capped = { ...missed, elapsedMs: MAX_ELAPSED_MS };
    expect(advanceGame(capped, 800).selection).toEqual({ kind: 'closed' });
    expect(advanceGame(capped, 800).elapsedMs).toBe(MAX_ELAPSED_MS);
    expect(activateCard({ ...activateCard(initial(), 0), moves: MAX_MOVES }, 11).moves).toBe(MAX_MOVES);
    for (const delta of [0, -1, NaN, Infinity]) expect(advanceGame(missed, delta)).toBe(missed);
  });

  it.each(GRID_SIZES)('finishes size %i and freezes time at the final match', (size) => {
    let state = initial(`np1-${size}-1`);
    for (let face = 0; face < size * size / 2; face += 1) {
      const first = state.board.deck.indexOf(face);
      const second = state.board.deck.lastIndexOf(face);
      state = activateCard(advanceGame(activateCard(state, first), 10), second);
    }
    expect(isWon(state)).toBe(true);
    expect(pairCount(state)).toBe(size * size / 2);
    expect(state.moves).toBe(size * size / 2);
    expect(advanceGame(state, 1000)).toBe(state);
    expect(activateCard(state, 0)).toBe(state);
  });

  it('formats uncapped minutes and floors seconds', () => {
    expect(formatTime(999)).toBe('0:00');
    expect(formatTime(61_999)).toBe('1:01');
    expect(formatTime(3_600_000)).toBe('60:00');
    expect(formatTime(MAX_ELAPSED_MS)).toBe('5999:59');
  });
});
import { describe, expect, it } from 'vitest';
import { replayGame, REPLAY_MAX_ACTIONS, REPLAY_MAX_BYTES } from './replay.ts';
import { MAX_ELAPSED_MS } from './state.ts';
import { parseLimitedJson } from './validation.ts';

const base = { version: 1, boardCode: 'np1-4-1', actions: [], endMs: 0 };

describe('version 1 replays', () => {
  it('matches the documented example and starts elapsed time at the first reveal', () => {
    const state = replayGame(JSON.stringify({ ...base,
      actions: [{ atMs: 0, index: 0 }, { atMs: 0, index: 11 }], endMs: 800 }));
    expect(state?.matched).toEqual([0, 11]);
    expect(state?.moves).toBe(1);
    expect(state?.elapsedMs).toBe(800);
    expect(replayGame(JSON.stringify({ ...base, actions: [{ atMs: 500, index: 0 }], endMs: 800 }))?.elapsedMs).toBe(300);
    expect(replayGame(JSON.stringify({ ...base, endMs: Number.MAX_SAFE_INTEGER }))?.elapsedMs).toBe(0);
  });

  it('resolves a mismatch before an equal-time action and preserves array order', () => {
    const actions = [{ atMs: 0, index: 0 }, { atMs: 0, index: 1 },
      { atMs: 799, index: 2 }, { atMs: 800, index: 1 }, { atMs: 800, index: 9 }];
    const state = replayGame(JSON.stringify({ ...base, actions, endMs: 800 }));
    expect(state?.moves).toBe(2);
    expect(state?.matched).toEqual([1, 9]);
    expect(state?.selection).toEqual({ kind: 'closed' });
    expect(replayGame(JSON.stringify({ ...base, actions: actions.slice(0, 4), endMs: 800 }))?.selection)
      .toEqual({ kind: 'one', index: 1 });
  });

  it('accepts safe integer timeline limits while capping elapsed time', () => {
    const state = replayGame(JSON.stringify({ ...base,
      actions: [{ atMs: 0, index: 0 }], endMs: Number.MAX_SAFE_INTEGER }));
    expect(state?.elapsedMs).toBe(MAX_ELAPSED_MS);
  });

