import { useCallback, useRef, useState } from 'react';
import { isGridSize } from '../boardCode.ts';
import { decodeSnapshot, encodeSnapshot } from '../snapshot.ts';
import { activateCard, createGame, isWon } from '../state.ts';
import type { GameState } from '../state.ts';
import { announce, turnResult } from './announcements.ts';
import { freshGame } from './seed.ts';
import { initialSession } from './sessionState.ts';
import type { SessionState } from './sessionState.ts';
import { browserStorage, readPreferences, saveBest, saveSize } from './storage.ts';
import { useSessionClock } from './useClock.ts';

export function useSession() {
  const [initial] = useState(() => {
    const storage = browserStorage();
    const preferences = readPreferences(storage);
    return { storage, state: initialSession(freshGame(preferences.size), preferences.bests) };
  });
  const [state, setState] = useState(initial.state);
  const current = useRef(state);
  const publish = useCallback((next: SessionState) => {
    if (next === current.current) return;
    current.current = next;
    setState(next);
  }, []);
  const { sample, resetClock } = useSessionClock(current, publish);

  function status(text: string): void {
    const previous = sample();
    publish({ ...previous, loadStatus: text, announcement: announce(previous.announcement, text) });
  }

  function replace(game: GameState, paused = false, loadStatus = ''): void {
    const previous = current.current;
    resetClock();
    publish({ ...previous, game, paused, celebrate: false, resetId: previous.resetId + 1,
      loadStatus, announcement: announce(previous.announcement, loadStatus) });
    saveSize(initial.storage, game.board.size);
  }

  function activate(index: number): void {
    const previous = sample();
    if (previous.paused) return;
    const game = activateCard(previous.game, index);
    const text = turnResult(previous.game, game);
    let bests = previous.bests;
    const won = game !== previous.game && isWon(game);
    if (won) {
      const best = bests[game.board.size];
      if (best === undefined || game.moves < best) {
        bests = { ...bests, [game.board.size]: game.moves };
        saveBest(initial.storage, game.board.size, game.moves);
      }
    }
    publish({ ...previous, game, bests, celebrate: previous.celebrate || won,
      announcement: text === null ? previous.announcement : announce(previous.announcement, text) });
  }

  function loadBoard(text: string): boolean {
    const game = createGame(text.trim());
    if (game === null) { status('Invalid board code.'); return false; }
    replace(game, false, 'Loaded board.');
    return true;
  }

  function loadSnapshot(text: string): boolean {
    const game = decodeSnapshot(text);
    if (game === null) { status('Invalid snapshot.'); return false; }
    const completed = isWon(game);
    replace(game, !completed, completed ? 'Loaded completed snapshot.' : 'Loaded snapshot. Select Resume to continue.');
    return true;
  }

  return {
    game: state.game, paused: state.paused, celebrate: state.celebrate, resetId: state.resetId,
    best: state.bests[state.game.board.size] ?? null,
    announcement: state.announcement, loadStatus: state.loadStatus,
    activate, loadBoard, loadSnapshot,
    newGame: () => replace(freshGame(current.current.game.board.size, current.current.game.board.seed)),
    restart: () => {
      const game = createGame(current.current.game.board.code);
      if (game !== null) replace(game);
    },
    changeSize: (value: unknown) => {
      if (isGridSize(value) && value !== current.current.game.board.size) {
        replace(freshGame(value, current.current.game.board.seed));
      }
    },
    exportSnapshot: (): string => {
      const next = sample();
      publish(next);
      return encodeSnapshot(next.game);
    },
    resume: () => {
      if (!current.current.paused) return;
      resetClock();
      publish({ ...current.current, paused: false });
    },
  };
}

export type GameSession = ReturnType<typeof useSession>;
import { advanceGame } from '../state.ts';
import type { GameState } from '../state.ts';

// This clock owns only its sampling anchor; game time remains in the pure core.
export function createActiveClock(atMs: number, visible: boolean) {
  let anchorMs = atMs;
  let shown = visible;

  function advance(game: GameState, paused: boolean, nowMs: number): GameState {
    const delta = shown && !paused ? Math.max(0, nowMs - anchorMs) : 0;
    anchorMs = nowMs;
    return advanceGame(game, delta);
  }

  return {
    advance,
    setVisible(game: GameState, paused: boolean, nowMs: number, nextVisible: boolean): GameState {
      const advanced = advance(game, paused, nowMs);
      shown = nextVisible;
      return advanced;
    },
    reset(nowMs: number, nextVisible: boolean): void {
      anchorMs = nowMs;
      shown = nextVisible;
    },
  };
}
import { GRID_SIZES, isGridSize } from '../boardCode.ts';
import type { GridSize } from '../boardCode.ts';
import { MAX_MOVES } from '../state.ts';
import { isInteger } from '../validation.ts';

export type SessionStorage = Pick<Storage, 'getItem' | 'setItem'>;
export type BestScores = Readonly<Partial<Record<GridSize, number>>>;
export const SIZE_KEY = 'neon-pairs.size';
export const bestKey = (size: GridSize): string => `neon-pairs.best.${size}`;

export function browserStorage(): SessionStorage | null {
  try { return window.localStorage; } catch { return null; }
}

function read(storage: SessionStorage | null, key: string): unknown {
  try {
    const text = storage?.getItem(key);
    const value: unknown = text == null ? null : JSON.parse(text);
    return value;
  } catch { return null; }
}

export function readPreferences(storage: SessionStorage | null): Readonly<{ size: GridSize; bests: BestScores }> {
  const savedSize = read(storage, SIZE_KEY);
  const bests: Partial<Record<GridSize, number>> = {};
  for (const size of GRID_SIZES) {
    const score = read(storage, bestKey(size));
    if (isInteger(score, MAX_MOVES)) bests[size] = score;
  }
  return { size: isGridSize(savedSize) ? savedSize : 4, bests };
}

function write(storage: SessionStorage | null, key: string, value: number): void {
  try { storage?.setItem(key, JSON.stringify(value)); } catch { /* Play continues in memory. */ }
}

export function saveSize(storage: SessionStorage | null, size: GridSize): void {
  write(storage, SIZE_KEY, size);
}

export function saveBest(storage: SessionStorage | null, size: GridSize, moves: number): void {
  write(storage, bestKey(size), moves);
}

import { useCallback, useEffect, useState } from 'react';
import type { RefObject } from 'react';
import { createActiveClock } from './clock.ts';
import type { SessionState } from './sessionState.ts';

export function useSessionClock(current: RefObject<SessionState>, publish: (next: SessionState) => void) {
  const [clock] = useState(() => createActiveClock(performance.now(), !document.hidden));
  const resetId = current.current.resetId;
  const sample = useCallback((): SessionState => {
    const state = current.current;
    const game = clock.advance(state.game, state.paused, performance.now());
    return game === state.game ? state : { ...state, game };
  }, [clock, current]);
  const resetClock = useCallback(() => clock.reset(performance.now(), !document.hidden), [clock]);

  useEffect(() => {
    let active = true;
    let timeout: number;
    const valid = () => active && current.current.resetId === resetId;
    const schedule = () => {
      const state = current.current;
      const delay = state.game.selection.kind === 'mismatch' && !state.paused && !document.hidden
        ? Math.max(1, Math.min(50, state.game.selection.remainingMs)) : 50;
      timeout = window.setTimeout(tick, delay);
    };
    const tick = () => {
      if (!valid()) return;
      publish(sample());
      schedule();
    };
    const visibility = () => {
      if (!valid()) return;
      const state = current.current;
      const game = clock.setVisible(state.game, state.paused, performance.now(), !document.hidden);
      publish(game === state.game ? state : { ...state, game });
    };
    document.addEventListener('visibilitychange', visibility);
    schedule();
    return () => {
      active = false;
      window.clearTimeout(timeout);
      document.removeEventListener('visibilitychange', visibility);
    };
  }, [clock, current, publish, resetId, sample]);

  return { sample, resetClock };
}
