    const gesture = async (distance: number) => session.send('Input.synthesizeScrollGesture', {
      x: rect.x + rect.width / 2, y: rect.y + rect.height / 2,
      xDistance: width === 360 ? distance : 0, yDistance: distance,
      speed: 4000, gestureSourceType: 'touch', preventFling: true,
    });
    await gesture(-2000);
    await expect(cards(page).last()).toBeInViewport();
    await gesture(2000);
    await expect(cards(page).first()).toBeInViewport();
    expect(await page.evaluate(() => document.documentElement.scrollWidth === innerWidth)).toBe(true);
    await session.detach();
  });
}
